#include<iostream>
#include<string>
#include<vector>
#include<queue>
using namespace std;

int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, 1, 0, -1};
int N;
vector<string> mat;
vector<string> mat2;
vector<vector<int>> v1;

void ff(int x, int y, vector<vector<int>>& v) {
    queue<int> q;
    q.push(x * N + y);
    while (!q.empty()) {
        int cur = q.front(); q.pop();
        x = cur / N;
        y = cur % N;
        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];
            if (nx < 0 || nx >= N || ny < 0 || ny >= N || v[nx][ny] != -1 || mat[nx][ny] == 'Y')
                continue;
            if (isdigit(mat2[nx][ny]) && mat2[nx][ny] != '0' && (v[x][y] + 1 <= v1[nx][ny] || v1[nx][ny] == -1)) {
                v[nx][ny] = v[x][y] + 1;
                if (v[nx][ny] != v1[nx][ny])
                    q.push(nx * N + ny);
            } else if (v1[nx][ny] == -1 || v1[nx][ny] > v[x][y] + 1) {
                v[nx][ny] = v[x][y] + 1;
                q.push(nx * N + ny);
            }
        }
    }
}

void ini(int x, int y, vector<vector<int>>& v) {
    v.assign(N, vector<int>(N, -1));
    v[x][y] = 0;
    ff(x, y, v);
}

void get(vector<string> m, vector<vector<vector<int>>>& v) {
    v.resize(N * N);
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if (isdigit(m[i][j]) && m[i][j] != '0')
                ini(i, j, v[i * N + j]);
}

const int INF = 1000000000;

struct Edge {
    int from, to, cost, flow;
    Edge(int f, int t, int c, int fl) : from(f), to(t), cost(c), flow(fl) {}
};

struct MinCostMaxFlow {
    int Nodes;
    vector<int> dist, flow, parent;
    vector<Edge> edges;
    int total_cost, total_flow;

    void clear(int n) {
        Nodes = n;
        dist.assign(n, INF);
        flow.assign(n, 0);
        parent.assign(n, 0);
    }

    void add_edge(int from, int to, int cost, int flow) {
        edges.emplace_back(from, to, cost, flow);
        edges.emplace_back(to, from, -cost, 0);
    }

    void bellman_ford(int src, int sink) {
        clear(Nodes);
        flow[src] = INF;
        dist[src] = 0;
        bool updated;
        for (int iter = 0; iter < Nodes; iter++) {
            updated = false;
            for (size_t i = 0; i < edges.size(); i++) {
                auto& e = edges[i];
                if (e.flow > 0 && dist[e.to] > dist[e.from] + e.cost) {
                    dist[e.to] = dist[e.from] + e.cost;
                    flow[e.to] = min(flow[e.from], e.flow);
                    parent[e.to] = i;
                    updated = true;
                }
            }
            if (!updated) break;
        }
    }

    void compute_min_cost_flow(int src, int sink) {
        if (src == sink) {
            total_cost = 0;
            total_flow = INF;
            return;
        }
        total_cost = 0;
        total_flow = 0;
        while (true) {
            bellman_ford(src, sink);
            if (flow[sink] == 0) break;
            for (int cur = sink; cur != src; cur = edges[parent[cur]].from) {
                int rev_idx = parent[cur] % 2 ? parent[cur] - 1 : parent[cur] + 1;
                edges[parent[cur]].flow -= flow[sink];
                edges[rev_idx].flow += flow[sink];
                total_cost += edges[parent[cur]].cost * flow[sink];
            }
            total_flow += flow[sink];
        }
    }
};

#define IN(a) (2 * (a))
#define OUT(a) (2 * (a) + 1)

MinCostMaxFlow mcf;

void add_edge(int i, int j, int x, int y) {
    int n1 = i * N + j;
    int n2 = x * N + y + N * N;
    mcf.add_edge(OUT(n1), IN(n2), 0, 1000000);
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("in.txt", "rt", stdin);
#endif
    int n, t;
    cin >> n >> t;
    vector<string> a(n), b(n);
    N = n;
    int si = -1, sj = -1;
    for (int i = 0; i < n; i++) {
        cin >> a[i];
        for (int j = 0; j < n; j++)
            if (a[i][j] == 'Z') {
                si = i;
                sj = j;
            }
    }
    mat = a;
    for (int i = 0; i < n; i++)
        cin >> b[i];
    mat2 = b;
    vector<vector<int>> v;
    vector<vector<vector<int>>> vv;
    v1.assign(N, vector<int>(N, INF));
    ini(si, sj, v);
    v1 = v;
    get(a, vv);
    mcf.clear(4 * N * N + 2);
    int src = 4 * N * N;
    for (int i = 0; i < N * N; i++) {
        mcf.add_edge(src, IN(i), 0, 1000000);
        mcf.add_edge(OUT(N * N + i), src + 1, 0, 1000000);
    }
    for (int x = 0; x < N; x++)
        for (int y = 0; y < N; y++) {
            if (isdigit(a[x][y])) {
                int k = x * N + y;
                mcf.add_edge(IN(k), OUT(k), 0, a[x][y] - '0');
            }
            if (isdigit(b[x][y])) {
                int k = x * N + y + N * N;
                mcf.add_edge(IN(k), OUT(k), 0, b[x][y] - '0');
            }
        }
    for (int i = 0; i < N; i++)
        for (int j = 0; j < N; j++)
            if (isdigit(b[i][j]) && b[i][j] != '0') {
                for (int k = 0; k < (int)vv.size(); k++) {
                    if (!vv[k].empty()) {
                        int x = k / N;
                        int y = k % N;
                        if (vv[k][i][j] == -1 || vv[k][i][j] > t) continue;
                        add_edge(x, y, i, j);
                    }
                }
            }
    mcf.compute_min_cost_flow(src, src + 1);
    cout << mcf.total_flow << endl;
    return 0;
}
